INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(27701, '2 Corinthians 2:10', '2 Corinthians', 2, 10, '&nbsp;هر څوک چې تاسو معاف کوئ هغه زۀ هم معاف کوم، ځکه څۀ چې ما معاف کړل دا ما ستاسو دپاره د مسيح په اختيار معاف کړل،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27702, '2 Corinthians 2:11', '2 Corinthians', 2, 11, '&nbsp;او دا د دې دپاره کوُو چې د شېطان په چال کښې راګېر نۀ شُو ځکه چې مونږ د هغۀ د منصوبو نه ناخبره نۀ يُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27703, '2 Corinthians 2:12', '2 Corinthians', 2, 12, '&nbsp;کله چې زۀ د مسيح زېرى ورکولو له ترواس ښار ته راغلم نو مالِک زما نه وړاندې د خدمت دروازه کولاو کړې وه،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27704, '2 Corinthians 2:13', '2 Corinthians', 2, 13, '&nbsp;خو زما روح آرام ونۀ موندو ځکه چې ما خپل ورور تيطوس هلته ونۀ ليدلو، نو د هغوئ نه مې رُخصت راواخستو او مِکدونيه ته لاړم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27705, '2 Corinthians 2:14', '2 Corinthians', 2, 14, '&nbsp;خو د خُدائ پاک شُکر دے چې مونږ يې د هغۀ غلامان کړو او د مسيح د کاميابۍ په جلوس کښې يې روان کړو. او زمونږ تعلق يې د مسيح د پېژندګلو په حقله لکه خوشبوئى په هر ځائ کښې خور کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27706, '2 Corinthians 2:15', '2 Corinthians', 2, 15, '&nbsp;مونږ د هر هغه چا دپاره چې خلاصون مومى او يا هلاک کيږى د خُدائ پاک دپاره د مسيح خوشبوئى يُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27707, '2 Corinthians 2:16', '2 Corinthians', 2, 16, '&nbsp;مونږ هغوئ ته څوک چې مړۀ کيږى د هلاکېدو بوئ يُو او هغوئ څوک چې ژوندى کيږى ورته د ژوندون بوئ يُو. او دغه شان کار څوک کولے شى؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27708, '2 Corinthians 2:17', '2 Corinthians', 2, 17, '&nbsp;ځکه چې مونږ د ډېرو خلقو په شان د خُدائ پاک کلام خرڅوونکى نۀ يُو بلکې مونږ د زړۀ د اخلاصه د مسيح په اختيار د خُدائ پاک کلام اورو. او په دې پوهه يُو چې د بره نه خُدائ پاک په مونږ نظر ساتى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27709, '2 Corinthians 3:1', '2 Corinthians', 3, 1, '&nbsp;ولې بيا مونږ د خپلې نېک نامۍ ډنډوره غږوو؟ او يا مونږ ته لکه د نورو خلقو په شان د سفارشى خطونو ضرورت دے څۀ؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27710, '2 Corinthians 3:2', '2 Corinthians', 3, 2, '&nbsp;تاسو په خپله زمونږ هغه سفارشى خط يئ چې زمونږ په زړونو ليکلے شوے دے، چې تاسو ټول يې لوستلے شئ او پرې پوهېږئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27711, '2 Corinthians 3:3', '2 Corinthians', 3, 3, '&nbsp;او ستاسو نه دا ظاهريږى چې په خپله لکه د مسيح د خط په شان يئ، کوم چې مونږ په سياهى نۀ دے ليکلے، بلکې د ژوندى خُدائ پاک په روح مو ليکلے دے نه چې د کاڼى په تختو بلکې په زړونو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27712, '2 Corinthians 3:4', '2 Corinthians', 3, 4, '&nbsp;خو مونږ دا خبره په يقين سره کوُو ځکه چې په مسيح کښې په خُدائ پاک زمونږ دغه شان باور دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27713, '2 Corinthians 3:5', '2 Corinthians', 3, 5, '&nbsp;مونږ په خپله د دې قابل نۀ يُو چې په خپله د څۀ کولو دعوىٰ وکړو بلکې زمونږ قابليت د خُدائ پاک د خوا نه دے،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27714, '2 Corinthians 3:6', '2 Corinthians', 3, 6, '&nbsp;چا چې مونږ د خپل نوى لوظ د خادِم کېدو جوګه کړو، دا لوظ د ليکلے شوى شريعت نه نۀ دے، بلکې د روح نه دے. ځکه چې زوړ ليکلے شوے شريعت وژل کوى، خو د نوې لوظ لاندې روح ژوند ورکوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27715, '2 Corinthians 3:7', '2 Corinthians', 3, 7, '&nbsp;کۀ د شريعت هغه تختې چې په ګټه ليکلے شوې وې او په هغې کښې دومره جلال وو چې بنى اِسرائيلو د موسىٰ مخ ته نۀ شو کتلے چې په کښې د خُدائ پاک جلال ځلېدو، کۀ څۀ هم هغه جلال به لږ وخت وروستو تتېدو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27716, '2 Corinthians 3:8', '2 Corinthians', 3, 8, '&nbsp;نو بيا ولې د روحُ القُدس د نظام جلال به د دې نه زيات نۀ وى څۀ؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27717, '2 Corinthians 3:9', '2 Corinthians', 3, 9, '&nbsp;ځکه کۀ په مجرمونکى نظام کښې جلال وو، نو صادقه نظام به ضرور د دې نه زيات جلالى وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27718, '2 Corinthians 3:10', '2 Corinthians', 3, 10, '&nbsp;حقيقت کښې چې مخکښې کوم جلال وو هغه اوس د دې لوئ جلال په وجه ختم شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27719, '2 Corinthians 3:11', '2 Corinthians', 3, 11, '&nbsp;نو چې فنا کېدونکى څيزونه جلالى وُو نو نوې ابدى څيزونه به ضرور د دې نه زيات جلالى وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27720, '2 Corinthians 3:12', '2 Corinthians', 3, 12, '&nbsp;نو زمونږ اُميد هم دا دے او په دې وجه په زړۀ ورتيا سره د زيرى اورولو خِدمت کوُو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27721, '2 Corinthians 3:13', '2 Corinthians', 3, 13, '&nbsp;او مونږ د موسىٰ په شان نۀ يو، چې په خپل مخ يې پړده اچولې وه د دې دپاره چې بنى اِسرائيل هغه جلال ونۀ ګورى کوم چې به لږ وخت وروستو تتېدو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27722, '2 Corinthians 3:14', '2 Corinthians', 3, 14, '&nbsp;خو د هغوئ زړونه سخت شول ځکه چې تر نن پورې د زوړ لوظ د تلاوت په وخت د هغوئ په زړونو پړده پرته ده، او دا پړده صرف د مسيح په وسيله اخوا کيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27723, '2 Corinthians 3:15', '2 Corinthians', 3, 15, '&nbsp;خو تر ننه پورې چې کله هم د موسىٰ کِتاب تلاوت کيږى نو د هغوئ په زړونو پړده پرته وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27724, '2 Corinthians 3:16', '2 Corinthians', 3, 16, '&nbsp;خو کله چې څوک د مالِک طرف ته راوګرځى، نو دغه پړده اخوا کيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27725, '2 Corinthians 3:17', '2 Corinthians', 3, 17, '&nbsp;اوس مالِک روح دے، او چرته چې د مالِک روح دے، هلته آزادى ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27726, '2 Corinthians 3:18', '2 Corinthians', 3, 18, '&nbsp;خو په مونږ کښې د مالِک خُدائ هغه جلال ليدل کيږى چا چې د خپلو مخونو نه پړده اخوا کړې ده، او مونږ ورځ په ورځ د مالِک خُدائ د جلال په صورت بدليږو، او دا کار زمونږ نه، خو د هغه مالِک دے چې په خپله روح دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27727, '2 Corinthians 4:1', '2 Corinthians', 4, 1, '&nbsp;نو ځکه چې مونږ ته د خُدائ پاک د رحم په وسيله دا خِدمت وسپارلے شو نو مونږ همت نۀ بائيلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27728, '2 Corinthians 4:2', '2 Corinthians', 4, 2, '&nbsp;مونږ ټول شرمناک کارونه پرېښودل، نۀ مونږ چالاکى کوُو او نۀ د خُدائ پاک په کلام کښې بدلون راولو. خُدائ پاک په خپله زمونږ ګواه دے چې همېشه رښتيا وايو او دا حقيقت ټولو صادقانو ته زمونږ رښتينوالى څرګندوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27729, '2 Corinthians 4:3', '2 Corinthians', 4, 3, '&nbsp;او کۀ چرې زمونږ په زېرى پړده پرته ده نو دا د هغوئ نه پټه ده څوک چې هلاکېدونکى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27730, '2 Corinthians 4:4', '2 Corinthians', 4, 4, '&nbsp;شېطان يعنې د دې دُنيا بادشاه د بې‌ايمانانو عقل ړوند کړے دے د دې دپاره چې هغوئ د مسيح په حقله د زيرى د جلال هغه رڼا ونۀ ګورى، څوک چې د خُدائ پاک په صورت دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27731, '2 Corinthians 4:5', '2 Corinthians', 4, 5, '&nbsp;ځکه چې مونږ د خپل ځانونو تبليغ نه، بلکې د عيسىٰ مسيح تبليغ کوُو، چې هغه مالِک دے، او خپل ځانونه مونږ د عيسىٰ دپاره ستاسو غلامان کوُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27732, '2 Corinthians 4:6', '2 Corinthians', 4, 6, '&nbsp;ځکه چې خُدائ پاک په خپله دا فرمائيلى دى چې، ”د تيارې نه دې رڼا وځليږى،“ نو هغۀ زمونږ په زړونو کښې د خُدائ پاک د جلال د عِلم رڼا د عيسىٰ مسيح په مخ باندې وځلوله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27733, '2 Corinthians 4:7', '2 Corinthians', 4, 7, '&nbsp;په مونږ کښې چې د خاورين لوښو په مثال نازک يُو، يوه داسې لويه خزانه پرته ده. چې د دې خبرې اظهار ترې وشى چې دا لوئ قدرت د خُدائ پاک د خوا نه دے، نه چې زمونږ د خوا نه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27734, '2 Corinthians 4:8', '2 Corinthians', 4, 8, '&nbsp;مونږ د هرې خوا نه په مصيبتونو کښې راګېر يُو خو تباه کيږُو نه، مونږ خو پرېشانه کيږُو خو نا اُميده کيږُو نه،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27735, '2 Corinthians 4:9', '2 Corinthians', 4, 9, '&nbsp;مونږ زورول کيږُو خو پرېښودل کيږُو نه، مونږ وهل کيږُو خو هلاکيږو نه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27736, '2 Corinthians 4:10', '2 Corinthians', 4, 10, '&nbsp;مونږ همېشه په خپل بدن کښې د عيسىٰ مرګ ګرځوو نو چې د عيسىٰ ژوند هم زمونږ په بدنونو کښې ښکاره شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27737, '2 Corinthians 4:11', '2 Corinthians', 4, 11, '&nbsp;ځکه چې مونږ هره ورځ د عيسىٰ په وجه مرګ ته حواله کيږُو د دې دپاره چې د عيسىٰ ژوند زمونږ د فانى بدن نه څرګند شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27738, '2 Corinthians 4:12', '2 Corinthians', 4, 12, '&nbsp;نو مونږ مرګ سره مخ کيږُو د دې دپاره چې تاسو ته ابدى ژوند مِلاو شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27739, '2 Corinthians 4:13', '2 Corinthians', 4, 13, '&nbsp;خو ليکلے شوى دى چې، ”ما ايمان راوړو او ځکه مې خبرې وکړې،“ نو په مونږ کښې هم دغه شان ايمان دے نو مونږ هم ايمان راوړے دے او ځکه خبرې کوُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27740, '2 Corinthians 4:14', '2 Corinthians', 4, 14, '&nbsp;ځکه چې مونږ ته پته ده چا چې مالِک عيسىٰ ژوندے کړے دے هغه به مونږ هم د عيسىٰ سره ژوندى کړى او سره ستاسو به مو خپلې مخې ته حاضر کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27741, '2 Corinthians 4:15', '2 Corinthians', 4, 15, '&nbsp;څۀ چې مونږ په ځان تېروو هغه ستاسو د فائدې دپاره تېروو، او څنګه چې د خُدائ پاک فضل ډېرو خلقو ته ملاويږى نو خلق به هم ډېره شُکر ګزارى کوى، نو په دې به خُدائ ته نور جلال هم ملاويږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27742, '2 Corinthians 4:16', '2 Corinthians', 4, 16, '&nbsp;نو په دې وجه مونږ همت نۀ بائيلو. اګر کۀ چې زمونږ ظاهرى بدن ورو ورو ختميږى خو زمونږ باطنى بدن ورځ تر ورځ نوے کيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27743, '2 Corinthians 4:17', '2 Corinthians', 4, 17, '&nbsp;ځکه چې زمونږ د دغه لږ ساعت معمولى مصيبتونه زمونږ دپاره بې‌اندازې غېر معمولى او ابدى جلال پېدا کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27744, '2 Corinthians 4:18', '2 Corinthians', 4, 18, '&nbsp;نو ځکه مونږ په ليدلو څيزونو نه، بلکې په ناليدلو څيزونو نظر ساتو، ځکه څۀ چې ښکارى هغه فانى دى خو څۀ چې نۀ ښکارى هغه ابدى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27745, '2 Corinthians 5:1', '2 Corinthians', 5, 1, '&nbsp;ځکه چې مونږ ته دا پته ده چې زمونږ بدن لکه د دُنياوى خېمې په شان دے په کومه کښې چې مونږ اوسيږو او کله چې هغه راپرېوځى نو خُدائ پاک به مونږ ته په آسمان کښې ابدى کور راکړى کوم چې په انسانى لاسونو جوړ شوے نۀ وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27746, '2 Corinthians 5:2', '2 Corinthians', 5, 2, '&nbsp;مونږ په دې خېمه کښې د خپل آسمانى کور د داخلېدو په طمع زبيرګى کوُو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27747, '2 Corinthians 5:3', '2 Corinthians', 5, 3, '&nbsp;کۀ په حقيقت کښې کله مونږ په دې کښې داخل شو نو مونږ به بربنډ نۀ يُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27748, '2 Corinthians 5:4', '2 Corinthians', 5, 4, '&nbsp;مونږ اوس هم په دې خېمه کښې يُو او د بوج لاندې زبيرګى کوُو، ځکه چې مونږ خپل فانى لباس ويستل نۀ غواړو بلکې د دې دپاسه نور اغوستل غواړو نو چې ژوند هغه څۀ ختم کړى څۀ چې فانى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27749, '2 Corinthians 5:5', '2 Corinthians', 5, 5, '&nbsp;چا چې مونږ د دې کار دپاره تيار کړو هغه خُدائ پاک دے او هغۀ مونږ ته د ضمانت په طور خپل روح راکړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27750, '2 Corinthians 5:6', '2 Corinthians', 5, 6, '&nbsp;نو مونږ همېشه په دې ډاډه يُو اګر کۀ مونږ ته پته ده چې ترڅو چې مونږ د دې بدن په کور کښې يُو نو تر هغې د مالِک په کور کښې نۀ يُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
