(27752, '2 Corinthians 5:8', '2 Corinthians', 5, 8, '&nbsp;آو، مونږ په دې ډاډه يُو چې د بدن غوندې کور به پرېږدو او د مالِک سره اوسېدل به زيات خوښوو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27753, '2 Corinthians 5:9', '2 Corinthians', 5, 9, '&nbsp;نو کۀ مونږ په دې بدن کښې يُو او يا نۀ يُو، خو زمونږ مقصد صرف د مالِک خوشحالول دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27754, '2 Corinthians 5:10', '2 Corinthians', 5, 10, '&nbsp;ځکه چې مونږ ټول به ضرور د مسيح د عدالت په وړاندې حاضر شو، نو هلته به هر يو ته د خپل کار بدله مِلاو شى څۀ چې هغوئ په دې بدن کښې کړى وى کۀ هغه ښۀ وى او کۀ بد وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27755, '2 Corinthians 5:11', '2 Corinthians', 5, 11, '&nbsp;نو مونږ د مالِک خُدائ د يرې نه خبر يُو او د خلقو د پوهولو کوشش کوُو. خو خُدائ پاک ته په خپله زمونږ د اخلاص پته ده او اُميد دے چې ستاسو ضمير ته به هم پته وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27756, '2 Corinthians 5:12', '2 Corinthians', 5, 12, '&nbsp;نو مونږ خپله نېک نامى په تاسو بيا نۀ زياتوو بلکې مونږ په خپله تاسو له موقع درکوو چې په مونږ فخر وکړئ د دې دپاره چې تاسو هغوئ له جواب ورکولے شئ څوک چې په ظاهره فخر کوى خو په زړۀ کښې نه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27757, '2 Corinthians 5:13', '2 Corinthians', 5, 13, '&nbsp;ځکه کۀ مونږ په خود کښې نۀ يُو نو د خُدائ پاک دپاره يُو او کۀ په خود کښې يُو نو ستاسو دپاره يُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27758, '2 Corinthians 5:14', '2 Corinthians', 5, 14, '&nbsp;ځکه چې د مسيح مينه مونږ په دې مجبوروى، چې مونږ په دې پوهه شُو چې هغه يو د ټولو دپاره مړ شو نو مطلب يې دا شو چې ټول مړۀ شول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27759, '2 Corinthians 5:15', '2 Corinthians', 5, 15, '&nbsp;او هغه د ټولو دپاره مړ شو نو چې څوک ژوندى دى هغه دې د ځان دپاره نۀ وى ژوندى بلکې د هغۀ د خاطره دې ژوندى وى څوک چې د هغوئ دپاره مړ شو او بيا ژوندے شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27760, '2 Corinthians 5:16', '2 Corinthians', 5, 16, '&nbsp;نو اوس مونږ چا ته په انسانى نظر نۀ ګورو، لکه څنګه چې مونږ هم مسيح ته يو وخت په انسانى نظر کتل خو اوس داسې نۀ کوُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27761, '2 Corinthians 5:17', '2 Corinthians', 5, 17, '&nbsp;نو بيا کۀ څوک په مسيح کښې وى نو هغه نوے مخلوق دے. زاړۀ هر څۀ ختم شول، وګورئ هر څۀ نوى شول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27762, '2 Corinthians 5:18', '2 Corinthians', 5, 18, '&nbsp;دا ټول هر څۀ د خُدائ پاک له طرفه دى، چا چې د مسيح په وسيله مونږ سره روغه وکړه او هغۀ مونږ ته د صُلح کولو خِدمت وسپارلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27763, '2 Corinthians 5:19', '2 Corinthians', 5, 19, '&nbsp;مطلب دا چې خُدائ پاک د مسيح په وسيله دُنيا سره صُلح کوله، او د هغوئ نافرمانى يې د هغوئ خلاف حساب نۀ کړه او د صُلح راوستو پېغام يې زمونږ په حواله کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
