(27765, '2 Corinthians 5:21', '2 Corinthians', 5, 21, '&nbsp;خُدائ پاک مسيح زمونږ د ګناهونو دپاره فديه کړو چا چې کله هم ګناه نۀ وه کړې، د دې دپاره چې مونږ د هغۀ په وسيله د خُدائ پاک په وړاندې صادق ثابت شُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27766, '2 Corinthians 6:1', '2 Corinthians', 6, 1, '&nbsp;مونږ چې د خُدائ پاک په خِدمت کښې شريک يُو، تاسو ته دا مِنت کوُو چې د خُدائ پاک کوم فضل چې تاسو قبول کړے دے، هغه عبث مۀ ګڼئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27767, '2 Corinthians 6:2', '2 Corinthians', 6, 2, '&nbsp;ځکه چې هغه فرمائى، ”کله چې ستاسو د بچ کېدو وخت راغلو، نو ما په تاسو نظر وکړو او د مدد دپاره مې ستاسو فرياد واورېدو.“ وګورئ د بچ کېدو وخت اوس راغلے دے. وګورئ دا د خلاصون ورځ ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27768, '2 Corinthians 6:3', '2 Corinthians', 6, 3, '&nbsp;مونږ د چا په لار کښې خنډ نۀ جوړيږو د دې دپاره چې زمونږ په خِدمت کښې څۀ نقصان پېدا نۀ شى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27769, '2 Corinthians 6:4', '2 Corinthians', 6, 4, '&nbsp;بلکې د خُدائ پاک د خادِمانو په شان په هره خبره کښې مونږ خپل ځان ښکاره کوُو، او په ډېر صبر سره په مشکلاتو کښې، په سختو کښې او افتونو کښې،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
