(27771, '2 Corinthians 6:6', '2 Corinthians', 6, 6, '&nbsp;او بيا هم په پاکۍ، په عِلم، په صبر، په مهربانۍ، په روحُ القُدس او په بې‌ريا مينې سره ځان ښکاره کوُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27772, '2 Corinthians 6:7', '2 Corinthians', 6, 7, '&nbsp;مونږ په وفادارۍ سره حقيقت بيانوو او د خُدائ پاک قدرت راسره دے. مونږ په خپل ښى لاس او ګس لاس کښې د صداقت وسلې نيولى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
