(27776, '2 Corinthians 6:11', '2 Corinthians', 6, 11, '&nbsp;اے کورنتيانو، مونږ تاسو سره صفا خبرې وکړې او درسره د زړۀ نه مينه کوُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27777, '2 Corinthians 6:12', '2 Corinthians', 6, 12, '&nbsp;زمونږ په مينه کښې څۀ کمے نشته خو ستاسو په زړونو کښې شته.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27778, '2 Corinthians 6:13', '2 Corinthians', 6, 13, '&nbsp;زۀ درته لکه د خپلو ماشومانو دا خواست کوم چې په خپلو زړونو کښې مونږ ته ځائ راکړئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27779, '2 Corinthians 6:14', '2 Corinthians', 6, 14, '&nbsp;څوک چې په مسيح ايمان نۀ لرى، د هغوئ سره په جغ کښې مۀ ځئ. ځکه چې د صادقانو او د شريرانو په خپلو کښې څۀ تعلق وى؟ او د رڼا او تيارې په خپلو کښې د يو بل سره څۀ تعلق وى؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27780, '2 Corinthians 6:15', '2 Corinthians', 6, 15, '&nbsp;ولې د مسيح د شېطان سره څۀ قسم جوړښت شته؟ يا يو ايماندار د يو بې‌ايمانه سره څۀ تعلق ساتلے شى څۀ؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27781, '2 Corinthians 6:16', '2 Corinthians', 6, 16, '&nbsp;نو د خُدائ پاک د کور او د بُتانو په خپلو کښې د جوړښت امکان نشته، نو مونږ په خپله د ژوندى خُدائ پاک کور يُو لکه څنګه چې خُدائ پاک فرمائيلى دى چې، ”زۀ به په خپله په هغوئ کښې اوسم او په هغوئ کښې به ګرځم، او زۀ به د هغوئ خُدائ پاک يم او هغوئ به زما خلق وى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27782, '2 Corinthians 6:17', '2 Corinthians', 6, 17, '&nbsp;دې دپاره مالِک فرمائى چې، ”د هغوئ نه راوځئ او د هغوئ نه جدا شئ او يو ناپاک څيز له هم لاس ورنۀ وړئ، نو زۀ به تاسو قبول کړم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27783, '2 Corinthians 6:18', '2 Corinthians', 6, 18, '&nbsp;او زۀ به بيا ستاسو پلار يم او تاسو به زما زامن او لوڼه يئ، دا د مالِک قادر مطلق خُدائ وينا ده.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27784, '2 Corinthians 7:1', '2 Corinthians', 7, 1, '&nbsp;نو اے خوږو دوستانو، نو چې مونږ سره داسې وعدې شوې دى نو راځئ چې مونږ خپل ځانونه د هر قِسمه جسمانى او روحانى ناپاکو نه پاک کړُو او د خُدائ پاک د يرې نه خپل پاکوالے کمال ته ورسوو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27785, '2 Corinthians 7:2', '2 Corinthians', 7, 2, '&nbsp;مونږ ته په خپلو زړونو کښې ځائ راکړئ. مونږ د هيچا سره بد نۀ دى کړى، مونږ څوک نۀ دى بې‌لارې کړى، نۀ مو چا سره دوکه کړې ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27786, '2 Corinthians 7:3', '2 Corinthians', 7, 3, '&nbsp;زۀ دا ستاسو د ملامتولو دپاره نۀ وايم ځکه چې ما تاسو ته اول هم وئيلى دى چې تاسو زمونږ په زړونو کښې داسې يئ چې کۀ مرګ وى او کۀ ژوند، مونږ تاسو سره يو ځائ يُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27787, '2 Corinthians 7:4', '2 Corinthians', 7, 4, '&nbsp;زۀ په تاسو مطمئن يم او په تاسو ډېر فخر کوم. ما ته پوره تسلى حاصله ده او په خپلو ټولو مصيبتونو کښې بيا هم بې‌حده خوشحاله يم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27788, '2 Corinthians 7:5', '2 Corinthians', 7, 5, '&nbsp;کله چې مونږ مِکدونيه ته راغلو نو مونږ ته دلته هم هيڅ آرام نۀ وو، خو مونږ نه هر طرف ته تکليفونه وُو، زمونږ نه ګېرچاپېره جګړې وې او زمونږ په زړونو کښې يې يره وه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27789, '2 Corinthians 7:6', '2 Corinthians', 7, 6, '&nbsp;خو خُدائ پاک چې عاجزانو ته تسلى ورکوى نو د تيطوس په راتلو يې مونږ له تسلى راکړه،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27790, '2 Corinthians 7:7', '2 Corinthians', 7, 7, '&nbsp;او نۀ تش د هغۀ په راتلو بلکې د هغۀ په هغه تسلۍ چې تاسو هغۀ له ورکړې وه، څنګه چې هغۀ مونږ ته ستاسو د خواهش، ستاسو د خفګان او ما دپاره ستاسو د ليوالتيا ووئيل نو زۀ نور هم زيات خوشحاله شوم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27791, '2 Corinthians 7:8', '2 Corinthians', 7, 8, '&nbsp;کۀ زما په سخت خط تاسو غمژن شوى وئ نو زۀ په هغې پښېمانه نۀ يم، اګر چې ما په اول وخت کښې کوم غم چې د لږ وخت دپاره در ورسولو نو په هغې زۀ لږ پښېمانه وم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27792, '2 Corinthians 7:9', '2 Corinthians', 7, 9, '&nbsp;خو اوس زۀ په دې خبره خوشحاله يم، نۀ چې ستاسو په غم بلکې په دې چې ستاسو خفګان تاسو توبه ګار کړئ. ځکه چې دا غمژن کېدل د خُدائ پاک د خوا نه وو، دا ځکه چې تاسو ته زمونږ د طرف نه څۀ نقصان نۀ وو رسېدلے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27793, '2 Corinthians 7:10', '2 Corinthians', 7, 10, '&nbsp;ځکه چې د خُدائ پاک د مرضۍ غم داسې توبه راپېدا کوى چې اَنجام يې خلاصون دے او په هغې پښېمانه کېدل نشته، خو د دُنيا غم مرګ پېدا کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27794, '2 Corinthians 7:11', '2 Corinthians', 7, 11, '&nbsp;نو ګورئ دغه د خُدائ پاک د مرضۍ غم په تاسو کښې څومره سرګرمى، عُذر، خفګان، يره، شوق، جوش او غېرت پېدا کړو. تاسو په هر جوړ دا ثابت کړل چې تاسو په دې خبره کښې څومره بې‌ګناه يئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27795, '2 Corinthians 7:12', '2 Corinthians', 7, 12, '&nbsp;نو اګر چې ما تاسو ته وليکل، خو د دې مقصد دا نۀ وو چې څوک غلط کارونه کوى د هغوئ په حقله وليکم يا چا سره چې غلط کارونه کيږى د هغوئ په حقله وليکم، نه، بلکې د دې مقصد دا وو چې د مالِک خُدائ په وړاندې په تاسو ظاهره شى چې تاسو زمونږ دپاره څومره سرګرم يئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27796, '2 Corinthians 7:13', '2 Corinthians', 7, 13, '&nbsp;په دې زمونږ تسلى وشوه او دې تسلۍ سره سره مونږ د تيطوس په خوشحالۍ نور هم خوشحاله شُو ځکه چې ستاسو ټولو په وسيله د هغۀ زړۀ ته تسلى مِلاو شوه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27797, '2 Corinthians 7:14', '2 Corinthians', 7, 14, '&nbsp;ځکه کۀ ما د هغۀ په وړاندې ستاسو په باب کښې څۀ فخر وکړو نو شرمنده نۀ شوم بلکې څنګه چې مونږ تاسو ته ټولې خبرې په رښتيا وکړې نو هم هغه شان هغه فخر چې مونږ د تيطوس په وړاندې وکړو، هغه هم رښتيا ثابت شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27798, '2 Corinthians 7:15', '2 Corinthians', 7, 15, '&nbsp;او هر کله چې هغۀ ته ستاسو د ټولو فرمانبردارۍ راياديږى او چې تاسو څنګه په ويره او رپېدلو هغه قبول کړو نو تاسو سره د هغۀ د زړۀ مينه نوره هم زياتيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27799, '2 Corinthians 7:16', '2 Corinthians', 7, 16, '&nbsp;زۀ ځکه خوشحاله يم چې زما مکمل باور په تاسو دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27800, '2 Corinthians 8:1', '2 Corinthians', 8, 1, '&nbsp;زما وروڼو او خوېندو، مونږ غواړو چې تاسو د خُدائ پاک د هغه فضل په حقله خبر شئ کوم چې د مِکدونيه جماعتونو ته ورکړے شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');